/* First-person, camera-locked gun from the supplied forward-facing reference. */
(()=>{'use strict';
const holder=document.getElementById('ddWesternGunArm');if(!holder)return;
const original=holder.querySelector('svg');if(original)original.remove();
const img=document.createElement('img');img.id='ddReferencePovGun';img.alt='';img.draggable=false;
img.src='data:image/png;base64,';holder.append(img);
const row=document.createElement('label');row.id='ddWesternArmOption';
row.innerHTML='<input id="ddShowGunArm" type="checkbox"> Show first-person Western revolver';
const screen=document.querySelector('#settings .screenPanel');
if(screen){screen.querySelector('.titleSmall')?.insertAdjacentElement('afterend',row);}
const input=row.querySelector('input');let saved=null;try{saved=localStorage.getItem('dd_show_gun_arm')}catch(_){}
input.checked=saved==null?(window.DD_EXPORT_DEFAULTS?.showGunArm!==false):saved==='true';
input.addEventListener('change',()=>{try{localStorage.setItem('dd_show_gun_arm',String(input.checked))}catch(_){}});
let pointerX=.5,pointerY=.5,swayX=0,swayY=0,recoil=0,last=0,armLost=false,looseArm=null;holder.style.transform='translateX(-50%)';
// Custom animated player weapon art. Keep idle PNG and both animated GIFs
// on precisely the same camera-locked anchor; a fresh IMG restarts every action.
const ddWeaponActionAssets={shot:'data:image/gif;base64,',reload:'data:image/gif;base64,'};
const ddWeaponActionDuration={shot:1500,reload:2050};
// Browsers commonly share the animation clock of GIFs loaded from the same URL.
// Give every accepted shot its own object URL, so fast left-clicks always
// begin at frame zero rather than continuing a previously running flash.
const ddActionBlobCache={};
function ddFreshActionURL(kind){
 try{
  const src=ddWeaponActionAssets[kind];
  if(!src||!window.Blob||!window.URL?.createObjectURL)return {src,objectURL:false};
  if(!ddActionBlobCache[kind]){
   const base64=src.slice(src.indexOf(',')+1),bytes=atob(base64);
   const data=new Uint8Array(bytes.length);
   for(let i=0;i<bytes.length;i++)data[i]=bytes.charCodeAt(i);
   ddActionBlobCache[kind]=new Blob([data],{type:'image/gif'});
  }
  return {src:URL.createObjectURL(ddActionBlobCache[kind]),objectURL:true};
 }catch(err){console.warn('Fresh gun animation fallback',err);return {src:ddWeaponActionAssets[kind],objectURL:false};}
}
let ddActionObjectURL=null;
let ddActionImage=null,ddActionTimeout=null,ddActionVersion=0;
function ddStopAction(){
 ddActionVersion++;
 if(ddActionTimeout!==null){clearTimeout(ddActionTimeout);ddActionTimeout=null;}
 if(ddActionImage){ddActionImage.remove();ddActionImage=null;}
 if(ddActionObjectURL){URL.revokeObjectURL(ddActionObjectURL);ddActionObjectURL=null;}
 img.style.visibility='';
}
function ddWeaponAction(kind){
 if(armLost||!input.checked||!holder.classList.contains('visible'))return;
 const src=ddWeaponActionAssets[kind];if(!src)return;
 ddStopAction();
 const actionVersion=ddActionVersion;
 const animated=document.createElement('img');
 animated.alt='';animated.setAttribute('aria-hidden','true');animated.draggable=false;
 // These source GIFs have a tall clear margin above the muzzle. Scale to
 // match the stationary sleeve/barrel without cropping the shot flash.
 Object.assign(animated.style,{
  position:'absolute',width:'162%',height:'150%',left:'-39%',bottom:'0',
  maxWidth:'none',maxHeight:'none',objectFit:'fill',pointerEvents:'none',
  userSelect:'none',display:'block',visibility:'visible'
 });
 const fresh=ddFreshActionURL(kind);
 ddActionObjectURL=fresh.objectURL?fresh.src:null;
 animated.src=fresh.src;
 img.style.visibility='hidden';holder.appendChild(animated);ddActionImage=animated;
 ddActionTimeout=setTimeout(()=>{if(ddActionVersion===actionVersion)ddStopAction();},ddWeaponActionDuration[kind]);
}

function resetArm(){
 ddStopAction();
 armLost=false;
 if(looseArm){looseArm.remove();looseArm=null;}
 holder.style.visibility='';
}
function flyOff(){
 if(armLost)return;
 ddStopAction();
 armLost=true;
 const box=holder.getBoundingClientRect();
 // The actual player arm asset is an image, not a detachable GLB, so fly
 // its full visual as one dropped sleeve, glove and revolver. It is a view
 // effect only: the weapon state is governed by duelState.playerDisarmed.
 if(input.checked&&box.width>0&&box.height>0&&holder.classList.contains('visible')){
  const ghost=img.cloneNode(false);
  ghost.removeAttribute('id');ghost.setAttribute('aria-hidden','true');
  Object.assign(ghost.style,{position:'fixed',left:box.left+'px',top:box.top+'px',width:box.width+'px',height:box.height+'px',display:'block',objectFit:'contain',pointerEvents:'none',zIndex:'10001',transformOrigin:'50% 65%',filter:'drop-shadow(3px 9px 8px #000a)',willChange:'transform,opacity'});
  document.body.append(ghost);looseArm=ghost;
  // Immediately detach from the screen-aligned aiming position: fly away,
  // tumble and fall, never exposing the old arm beneath it.
  const side=pointerX<.5?1:-1;
  const frames=[
   {transform:'translate(0px,0px) rotate(0deg) scale(1)',opacity:1,offset:0},
   {transform:`translate(${side*90}px,-115px) rotate(${side*55}deg) scale(.88)`,opacity:1,offset:.24},
   {transform:`translate(${side*260}px,${Math.round(innerHeight*.4)}px) rotate(${side*205}deg) scale(.65)`,opacity:.83,offset:.75},
   {transform:`translate(${side*335}px,${Math.round(innerHeight*1.05)}px) rotate(${side*330}deg) scale(.48)`,opacity:0,offset:1}
  ];
  if(typeof ghost.animate==='function'){
   const animation=ghost.animate(frames,{duration:950,easing:'cubic-bezier(.18,.14,.46,1)',fill:'forwards'});
   animation.finished.then(()=>{if(looseArm===ghost)looseArm=null;ghost.remove();}).catch(()=>{if(looseArm===ghost)looseArm=null;ghost.remove();});
  }else{ghost.remove();looseArm=null;}
 }
 holder.style.visibility='hidden';
}

document.addEventListener('pointermove',e=>{pointerX=Math.max(0,Math.min(1,e.clientX/Math.max(1,innerWidth)));pointerY=Math.max(0,Math.min(1,e.clientY/Math.max(1,innerHeight)));},{passive:true});
document.addEventListener('pointerdown',e=>{const rt=window.__STRATIX_TEST__;if(e.button===0&&holder.classList.contains('visible')&&(!rt||rt.gun?.rounds>0))recoil=1;},{passive:true});
function frame(now){const rt=window.__STRATIX_TEST__;
const showing=input.checked&&rt?.mode==='custom'&&(rt?.state==='playing'||rt?.state==='countdown')&&!document.body.classList.contains('results');
holder.classList.toggle('visible',!!showing&&!armLost);
if(showing&&!armLost){const dt=Math.min(.06,Math.max(.001,(now-last)/1000||.016));const k=1-Math.exp(-dt*12);
const liveAim=window.DDGameAimView?.();
const visualX=liveAim?.holsterLocked ? 0.5 : (liveAim?.x ?? pointerX);
const visualY=liveAim?.holsterLocked ? 0.88 : (liveAim?.y ?? pointerY);
if(liveAim?.holsterLocked){swayX=0;swayY=.76;recoil=0;}else{swayX+=((visualX-.5)*2-swayX)*k;swayY+=((visualY-.5)*2-swayY)*k;}
// No horizontal flip, no 3D rotation and no perspective stretch: barrel always points away.
// Image is centered on the lower portion of the screen and cut below the viewport at every sway value.
holder.style.transform=`translate3d(calc(-50% + ${(swayX*Math.min(520,innerWidth*.42)).toFixed(1)}px),${(swayY*135+recoil*15).toFixed(1)}px,0) rotate(${(swayX*3.0).toFixed(2)}deg)`;
recoil=Math.max(0,recoil-dt*6);
}last=now;requestAnimationFrame(frame)}requestAnimationFrame(frame);
window.DDWesternGunArm={get enabled(){return input.checked},set enabled(v){input.checked=!!v;input.dispatchEvent(new Event('change'))},get meshReady(){return true},get imageBased(){return true},flyOff,reset:resetArm,animateAction:ddWeaponAction,get disarmed(){return armLost}};
})();